/// <summary>
/// designed from N.Freidenberger 14.05.2024
/// </summary>
public void initValue()
{
    next initValue();

    if (element.args().menuItemName() ==  menuItemDisplayStr(AVAsmmBusRelQuickCopy))
    {
        smmBusRelTable               copySmmBusRelTable = element.args().record();
        LogisticsPostalAddress       copyLogisticsPostalAddress  = copySmmBusRelTable.postalAddress();
        LogisticsPostalAddress       newLogisticsPostalAddress   = this.cursor();

        newLogisticsPostalAddress.NDXLogisticsLocationName1      = copyLogisticsPostalAddress.NDXLogisticsLocationName1;
        newLogisticsPostalAddress.NDXLogisticsLocationName2      = copyLogisticsPostalAddress.NDXLogisticsLocationName2;
        newLogisticsPostalAddress.NDXLogisticsLocationName3      = copyLogisticsPostalAddress.NDXLogisticsLocationName3;
    }
}
